query StoragePanelQuery {
  photographer {
    storage {
      totalBytes
      hotBytes
      archivedBytes
      archiveAvailable
      albums {
        albumId
        name
        photoCount
        bytes
        originalBytes
        archivedBytes
        transition
      }
    }
    id
  }
}

7251989edfa2dfaaf02a9ea96f773216:
mutation photoUploadAttachMutation(
  $id: ID!
  $files: [PhotoPromiseFileInput!]!
) {
  attachPhotoPromiseFiles(id: $id, files: $files) {
    files {
      id
      uploadUrl
      uploadHeaders
    }
  }
}

9a799d9216bf40c31339232ddb6099e1:
mutation photoUploadFinishMutation(
  $id: ID!
  $status: PhotoPromiseFileStatus!
) {
  updatePhotoPromiseFileUpdate(id: $id, status: $status) {
    file {
      status
      id
    }
  }
}

